import ast
from concurrent.futures import ThreadPoolExecutor, as_completed
import hashlib
import json
import os
from pathlib import Path
import re
import sys
import time
import urllib.request

sys.dont_write_bytecode = True
sys.path.insert(0, str(Path.cwd() / 'scripts/aws'))
from aws_cli import run, result, CLITimeout

OUT = Path('testdata/aws/cloudwatch/metric_insights_keywords.json')
SOURCE = Path('testdata/aws/cloudwatch/metric_insights.json')
REGION = 'us-west-2'
ACCOUNT = '000000000000'
ACTOR = 'arn:aws:iam::000000000000:user/Delegated'
URL = 'https://docs.aws.amazon.com/AmazonCloudWatch/latest/monitoring/cloudwatch-metrics-insights-reserved-keywords.html'
MD_URL = URL.removesuffix('.html') + '.md'
prior = json.loads(SOURCE.read_text())
NS = prior['namespace']
T = prior['sample_start_epoch']
assert NS == 'stackd/insights/6c84c6382d8f'
env = dict(os.environ, AWS_REGION=REGION, AWS_DEFAULT_REGION=REGION, AWS_MAX_ATTEMPTS='1', AWS_RETRY_MODE='standard', AWS_PAGER='', AWS_IGNORE_CONFIGURED_ENDPOINT_URLS='true', PYTHONDONTWRITEBYTECODE='1')
for key in list(env):
    if key.startswith('AWS_ENDPOINT_URL'):
        del env[key]

if OUT.exists():
    capture = json.loads(OUT.read_text())
else:
    fetched = time.time_ns() // 1000000
    with urllib.request.urlopen(MD_URL, timeout=30) as response:
        raw_document = response.read()
    document = raw_document.decode()
    block = document.split('```')[1]
    # The primary source omits FALLBACK's closing quote. Split tokens rather
    # than paired quote matches so this typo cannot silently shift the list.
    words = re.findall(r'[A-Z][A-Z0-9_-]*', block)
    assert len(words) == len(set(words)) and {'FALLBACK', 'FALSE', 'LOAD', 'ZONE', 'LIMIT'} <= set(words)
    capture = {
        'region': REGION, 'caller_account': ACCOUNT, 'actor_arn': ACTOR,
        'namespace': NS, 'sample_start_epoch': T, 'sample_end_epoch': T+180,
        'source_fixture': str(SOURCE),
        'sources': [], 'primary_references': [URL],
        'primary_source_capture': {'url': URL, 'retrieved_url': MD_URL, 'retrieved_at_ms': fetched, 'sha256': hashlib.sha256(raw_document).hexdigest(), 'content': document},
        'documented_words': words, 'observations': [],
        'cleanup': [], 'cleanup_verification': {'native_mutations': 'None. Only STS GetCallerIdentity and CloudWatch GetMetricData are called; existing owned samples are queried without publication or configuration changes.'},
        'measured_semantics': [], 'inferences': [], 'evidence_boundaries': ['Classification concerns syntactic identifier admission, not existence of metrics/dimensions or data availability. All CloudWatch requests use the original owned namespace and original 180-second sample window. Namespace-identifier admission is not measured because no unowned namespace is queried.']
    }
capture['sources'] = [{'path': __file__, 'content': Path(__file__).read_text()}, {'path': 'scripts/aws/aws_cli.py', 'content': Path('scripts/aws/aws_cli.py').read_text()}]

def save():
    OUT.write_text(json.dumps(capture, indent=2, ensure_ascii=False)+'\n')

def request(label, parameters, service='cloudwatch', operation='get-metric-data', **metadata):
    started = time.time_ns() // 1000000
    try:
        process = run(service, operation, parameters, env, options=['--region', REGION, '--no-paginate', '--debug', '--cli-connect-timeout', '10', '--cli-read-timeout', '30'], timeout=50)
        parsed = result(process, debug=True)
        headers = {}
        for text in re.findall(r'Response headers: (\{[^\n]+\})', process.stderr):
            try:
                headers = ast.literal_eval(text)
            except (ValueError, SyntaxError):
                pass
        request_id = next((v for k,v in headers.items() if k.lower() in ('x-amzn-requestid','x-amzn-request-id','x-amz-request-id')), None)
        if request_id:
            parsed['request_id'] = request_id
        for line in process.stderr.splitlines():
            if line.startswith(("b'", 'b"')):
                try:
                    body = ast.literal_eval(line)
                    if body.startswith(b'{'):
                        parsed['raw_response'] = json.loads(body)
                    elif body.startswith(b'<'):
                        parsed['raw_response'] = body.decode()
                except (ValueError, SyntaxError, UnicodeDecodeError):
                    pass
    except CLITimeout:
        parsed = {'code':'TransportTimeout', 'message':'Shared AWS CLI transport exceeded its 50-second bound; no native admission classification.'}
    return {'label':label, 'service':service, 'operation':operation, 'input':parameters, 'region':REGION, 'caller_account':ACCOUNT, 'actor_arn':ACTOR, 'request_started_ms':started, 'result':parsed, **metadata}

def expression(context, identifier):
    base = 'SELECT AVG(Load) FROM "'+NS+'"'
    if context == 'schema':
        return 'SELECT AVG(Load) FROM SCHEMA("'+NS+'", '+identifier+')'
    if context == 'metric':
        return 'SELECT AVG('+identifier+') FROM "'+NS+'"'
    if context == 'where':
        return base+' WHERE '+identifier+" = 'west'"
    if context == 'group':
        return base+' GROUP BY '+identifier
    raise ValueError(context)

def query(context, word, quoted=False, prefix='word'):
    label = '-'.join([prefix,context,'quoted' if quoted else 'unquoted',word])
    identifier = '"'+word+'"' if quoted else word
    params = {'StartTime':T, 'EndTime':T+180, 'MetricDataQueries':[{'Id':'q','Expression':expression(context,identifier),'Period':60}]}
    return request(label, params, identifier_context=context, identifier=word, quoted=quoted)

def admission(row):
    result = row['result']
    if result['code'] == 'Success':
        statuses = [x.get('StatusCode') for x in result.get('output',{}).get('MetricDataResults',[])]
        return 'accepted' if all(x == 'Complete' for x in statuses) else 'unresolved_service_result'
    if result['code'] in ('InvalidParameterValue','ValidationError') and 'syntax' in result.get('message','').lower():
        return 'rejected'
    return 'unresolved'

def batch(specifications):
    seen = {r['label'] for r in capture['observations']}
    specs = [x for x in specifications if '-'.join([x[3],x[0],'quoted' if x[2] else 'unquoted',x[1]]) not in seen]
    with ThreadPoolExecutor(max_workers=6) as executor:
        futures = [executor.submit(query,*spec) for spec in specs]
        for completed, future in enumerate(as_completed(futures),1):
            row = future.result()
            row['admission'] = admission(row)
            capture['observations'].append(row)
            if completed % 25 == 0 or row['admission'] not in ('accepted','rejected'):
                save()
                print(completed, '/',len(specs),row['label'],row['admission'], row['result']['code'],flush=True)
    save()

identity = request('identity-'+str(time.time_ns()), {}, 'sts', 'get-caller-identity')
assert identity['result']['code'] == 'Success', identity['result']
assert identity['result']['output']['Account'] == ACCOUNT
assert identity['result']['output']['Arn'] == ACTOR
capture['observations'].append(identity)
save()
mode = sys.argv[1]
if mode == 'controls':
    words = ['LOAD','Load','ZONE','Zone','LIMIT','SELECT','SCHEMA','AVG','AND','ABORT','USER','CURRENT_DATE','END-EXEC','AT','Team','Missing']
    batch([(context,word,quoted,'control') for context in ['schema','metric','where','group'] for word in words for quoted in [False,True]])
elif mode in ['schema','metric','where','group']:
    batch([(mode,word,False,'word') for word in capture['documented_words']])
elif mode == 'quoted-rejections':
    rejected = [(r['identifier_context'],r['identifier'],True,'word') for r in capture['observations'] if r.get('admission') == 'rejected' and not r.get('quoted') and r['label'].startswith('word-')]
    batch(rejected)
else:
    raise ValueError(mode)
counts = {}
for row in capture['observations']:
    if 'admission' in row:
        key = (row['identifier_context'], row['quoted'],row['admission'])
        counts[str(key)] = counts.get(str(key),0)+1
print(json.dumps(counts,indent=2),flush=True)

"""AWS CLI transport shared by native behavior probes.

Callers own endpoint/retry choices, observations and resource cleanup. JSON shapes
remain open because probes deliberately exercise invalid and newly added inputs.
"""
import ast
import json
import re
import subprocess
from collections.abc import Mapping, Sequence
from typing import Any, NotRequired, TypedDict


class ProbeResult(TypedDict):
    code: str
    output: NotRequired[dict[str, Any]]
    error: NotRequired[dict[str, Any]]
    message: NotRequired[str]
    http_status: NotRequired[int]


class CLITimeout(RuntimeError):
    """A bounded CLI call expired; command arguments may contain secrets."""


class AWSCLIError(RuntimeError):
    """A failed strict call, retaining native JSON error fields for its caller."""

    def __init__(self, service: str, operation: str, stderr: str, details: dict[str, Any]):
        super().__init__(f"{service}:{operation}: {stderr.strip()}")
        self.details = details


def run(service: str, operation: str, parameters: Mapping[str, Any] | None = None,
        env: Mapping[str, str] | None = None, *, options: Sequence[str] = (),
        timeout: float | None = None) -> subprocess.CompletedProcess[str]:
    """Execute one CLI command without interpreting service or client failures."""
    command = ["aws", service, operation, "--output", "json", "--no-cli-pager"]
    if parameters is not None:
        command += ["--cli-input-json", json.dumps(parameters)]
    try:
        return subprocess.run(command + list(options), env=env, capture_output=True,
                              text=True, check=False, timeout=timeout)
    except subprocess.TimeoutExpired:
        raise CLITimeout("AWS CLI timed out during " + operation) from None


def call(service: str, operation: str, parameters: Mapping[str, Any] | None = None,
         env: Mapping[str, str] | None = None, *, paginate: bool = True,
         error_format: str | None = None) -> dict[str, Any]:
    """Return JSON output; service and CLI-validation errors retain typed details.

    Configuration and transport failures abort capture instead of becoming
    observations of AWS behavior. AWS CLI uses 252 for input errors and 254
    for service errors.
    """
    options = ["--cli-connect-timeout", "10", "--cli-read-timeout", "30"]
    if error_format is not None:
        options += ["--cli-error-format", error_format]
    if not paginate:
        options.append("--no-paginate")
    process = run(service, operation, parameters or None, env, options=options)
    if process.returncode:
        diagnosis = f"{service}:{operation}: {process.stderr.strip()}"
        if error_format == "json" and process.returncode in (252, 254):
            try:
                details = json.loads(process.stderr)
            except json.JSONDecodeError:
                raise RuntimeError(diagnosis) from None
            if isinstance(details, dict) and isinstance(details.get("Code"), str):
                raise AWSCLIError(service, operation, process.stderr, details)
        raise RuntimeError(diagnosis)
    return result(process)["output"]


def observe(service: str, operation: str, parameters: Mapping[str, Any] | None = None,
            env: Mapping[str, str] | None = None, *, paginate: bool = True) -> ProbeResult:
    """Capture native JSON success/error fields; callers own output redaction."""
    try:
        output = call(service, operation, parameters, env, paginate=paginate, error_format="json")
    except AWSCLIError as error:
        return {"code": error.details["Code"], "error": error.details}
    return {"code": "Success", "output": output}


def _text_error(stderr: str) -> tuple[str, str | None]:
    match = re.search(r"An error occurred \(([^)]+)\)(?:.*?operation(?: \([^)]*\))?: (.*))?", stderr)
    return (match[1], match[2]) if match else ("CLIError", None)


def result(process: subprocess.CompletedProcess[str], *, cli_error: str = "CLIError",
           cli_message: str | None = "AWS CLI failed; raw diagnostics discarded",
           debug: bool = False) -> ProbeResult:
    """Decode an observation, separating modeled errors from CLI rejection.

    A None client message retains the final three diagnostic lines for probes
    whose captured CLI-validation observations include those lines.
    """
    if process.returncode:
        code, message = _text_error(process.stderr)
        decoded: ProbeResult = {
            "code": code if message is not None else cli_error,
            "message": message if message is not None else cli_message if cli_message is not None
            else " ".join(process.stderr.splitlines()[-3:]),
        }
    else:
        decoded = {"code": "Success", "output": json.loads(process.stdout) if process.stdout.strip() else {}}
    if debug:
        statuses = re.findall(r'"[A-Z]+ [^"\r\n]* HTTP/1\.[01]" (\d{3})', process.stderr)
        if statuses:
            decoded["http_status"] = int(statuses[-1])
    return decoded


def error_code(process: subprocess.CompletedProcess[str]) -> str:
    """Decode code-only observations, including CLI ParamValidation errors."""
    return _text_error(process.stderr)[0]


def raw_xml(process: subprocess.CompletedProcess[str]) -> bytes | None:
    """Extract the last XML response from CLI debug output; discard other logs."""
    raw = None
    for line in process.stderr.splitlines():
        if line.startswith(("b'<", 'b"<')):
            try:
                candidate = ast.literal_eval(line)
                if candidate.startswith(b"<"):
                    raw = candidate
            except (ValueError, SyntaxError):
                pass
    return raw
